private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Enlarging byte vector must be done with a positive size");
    }

    if (size == 0) {
        return;
    }

    // Allocate new memory to store the enlarged byte vector
    byte[] newMemory = new byte[this.size + size];

    // Copy the existing bytes to the new memory
    System.arraycopy(this.memory, 0, newMemory, 0, this.size);

    // Update the byte vector with the new memory
    this.memory = newMemory;
    this.size += size;
}

