public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        return Arrays.stream(parameterizedType.getActualTypeArguments())
                .map(type -> (type instanceof TypeVariable) ? getActualType(targetType, (TypeVariable) type) : type)
                .toArray(Class[]::new);
    }
    return null;
}

private static Class<?> getActualType(Class<?> targetType, TypeVariable typeVariable) {
    try {
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        for (TypeVariable<?> typeParameter : typeParameters) {
            if (typeParameter.getName().equals(typeVariable.getName())) {
                return (Class<?>) typeParameter.getGenericDeclaration();
            }
        }
    } catch (Exception e) {
        // exception handling
    }
    return Object.class;
}

