public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    // If the value is null or empty, return an empty string
    if (value == null || value.isEmpty()) {
        return "";
    }
    StringBuffer buffer = new StringBuffer();
    // Iterate over each character of the value
    for (int i = 0; i < value.length(); i++) {
        char c = value.charAt(i);
        // If the character is a dollar sign, perform variable substitution
        if (c == '$') {
            try {
                i++;
                // Extract the variable name from the value
                String varName = value.substring(i, i + 1);
                String varValue = props.getProperty(varName);
                // If the variable name is not found or the variable value is null or empty, substitute with an empty string
                if (varValue == null || varValue.isEmpty()) {
                    buffer.append("");
                } else {
                    buffer.append(varValue);
                }
            } catch (StringIndexOutOfBoundsException e) {
                buffer.append("");
            }
        } else {
            buffer.append(c);
        }
    }
    // Return the result of the variable substitution
    return buffer.toString();
}

