public static int nextPrime(int desiredCapacity) {

  // Handle invalid input
  if (desiredCapacity <= 0) {
    throw new IllegalArgumentException("desiredCapacity must be > 0");
  }

  // Find the prime number using a simple algorithm
  int candidate = desiredCapacity * 2;
  while (!isPrime(candidate)) {
    candidate += desiredCapacity;
  }
  return candidate;
}

private static boolean isPrime(int n) {
  if (n < 2) {
    return false;
  }
  int maxFactor = (int)Math.sqrt(n);
  for (int i = 2; i <= maxFactor; i++) {
    if (n % i == 0) {
      return false;
    }
  }
  return true;
}

