public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuffer buffer = new StringBuffer();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            c = str.charAt(i);
            if (c == 'n') {
                buffer.append("\n");
            } else if (c == 't') {
                buffer.append("\t");
            } else if (c == 'r') {
                buffer.append("\r");
            } else if (c == 'f') {
                buffer.append("\f");
            } else if (c == 'b') {
                buffer.append("\b");
            } else if (c == 'u') {
                buffer.append((char) Integer.parseInt(str.substring(i+1, i+5), 16));
                i += 4;
            } else {
                buffer.append(c);
            }
        } else {
            buffer.append(c);
        }
    }
    return buffer.toString();
}

