final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check that constantPoolEntryIndex is a valid index
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= charBuffer.length) {
        throw new IndexOutOfBoundsException("constantPoolEntryIndex is out of range");
    }
    final int stringLength = classFileBuffer.getU1(8 + constantPoolEntryIndex * 3);
    // Check that the string will fit in the buffer
    if (stringLength > charBuffer.length) {
        throw new StringIndexOutOfBoundsException("String is too long to fit in the buffer");
    }
    final int reference = classFileBuffer.getU1(8 + constantPoolEntryIndex * 3 + 1);
    // Check that the reference is within bounds
    if (reference < 0 || reference >= buffer.length) {
        throw new StringIndexOutOfBoundsException("String reference is out of range");
    }
    // Read the string into the buffer
    final char[] source = charBuffer.copy(reference, stringLength);
    final char[] dest = new char[stringLength];
    for (int i = 0; i < stringLength; i++) {
        dest[i] = source[i];
    }
    return new String(dest);
}

