public boolean isCompatible(DataTable dataset) {
    // Check if the DataTable is null or empty
    if (dataset == null || dataset.length == 0) {
        throw new IllegalArgumentException("The data table must not be null or empty.");
    }

    // Check if the DataTable has the same number of rows and columns as the bucket
    if (dataset.length != this.rows) {
        return false;
    }

    // Check if the DataTable has the same number of columns as the bucket
    if (dataset[0].length != this.cols) {
        return false;
    }

    // Check if the values in the DataTable are compatible with the bucket's values
    for (int i = 0; i < dataset.length; i++) {
        for (int j = 0; j < dataset[i].length; j++) {
            if (j >= this.cols) {
                return false;
            }
            double value = dataset[i][j];
            if (!this.bucket.containsValue(value)) {
                return false;
            }
        }
    }

    // All checks have passed, so the bucket is compatible
    return true;
}

