public ByteVector putInt(final int intValue) {
    // Check if the buffer needs to be enlarged to hold the new int
    int bytesNeeded = size() + 4;
    if (bytesNeeded > buffer.length) {
        buffer = Arrays.copyOf(buffer, bytesNeeded * 2);
    }

    // Store the int in little-endian format
    buffer[size()] = (byte) (intValue & 0xFF);
    buffer[size() + 1] = (byte) ((intValue >> 8) & 0xFF);
    buffer[size() + 2] = (byte) ((intValue >> 16) & 0xFF);
    buffer[size() + 3] = (byte) (intValue >> 24);

    // Update the size
    size += 4;

    // Return this byte vector
    return this;
}

