private static Type resolveBound(TypeVariable<?> typeVariable) {
    Type result = resolveTypeVariable(typeVariable);
    return result != null ? result : String.class;
}

private static Type resolveTypeVariable(TypeVariable<?> typeVariable) {
    Class<?> clazz = typeVariable.getGenericDeclaration() instanceof Class ? (Class<?>) typeVariable.getGenericDeclaration() : null;
    if (clazz == null) {
        return null;
    }
    Type type = clazz.getGenericSuperclass();
    while (!(type instanceof ParameterizedType)) {
        type = clazz.getGenericSuperclass();
        if (type == null) {
            return null;
        }
        clazz = (Class<?>) ((ParameterizedType) type).getRawType();
    }
    ParameterizedType parameterizedType = (ParameterizedType) type;
    int index = Arrays.asList(clazz.getTypeParameters()).indexOf(typeVariable);
    if (index < 0) {
        return null;
    }
    Type actualType = parameterizedType.getActualTypeArguments()[index];
    if (actualType instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) actualType);
    }
    return actualType;
}

private static <V,E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the number of vertices in the subgraph is equal to the number of vertices in the clique
    if (vertices.size() != graph.vertexSet().size()) {
        return false;
    }

    // Check if all vertices in the subgraph are connected to each other
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.adjacent(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int maxLowerBound = 0;
        for (int j = i+1; j < keys.size(); j++) {
            if (keys.get(j).compareTo(keys.get(i)) > 0) {
                maxLowerBound = Math.max(maxLowerBound, keys.get(j));
            }
        }
        lowerBounds.add(maxLowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    // extract the JVM names of the types from the descriptor
    final Set<String> types = Type.getArgumentTypes(descriptor);

    // check if the method descriptor describes a method with parameter types
    if (!types.isEmpty()) {
      // loop through the parameter types and pop each one from the output frame stack
      for (String type : types) {
        // get the JVM name of the type and convert it to a Java type
        final Class<?> clazz = Class.forName(type);

        // pop the type from the stack
        final Object value = stack.pop();

        // check if the value is assignable to the desired type
        if (!clazz.isAssignableFrom(value.getClass())) {
          throw new IllegalArgumentException("Attempted to pop a value of type " + value.getClass().getName() + " when type " + clazz.getName() + " was expected.");
        }
      }
    }
  }

