private List<Integer> computeUpperBounds(List<K> keys) {
    // use a Set to collect the unique keys
    Set<K> uniqueKeys = new HashSet<>(keys);

    // initialize the upper bounds with the minimum value of the keys
    List<Integer> upperBounds = new ArrayList<>(uniqueKeys.size());
    for (K key : uniqueKeys) {
        int upperBound = Collections.min(keys);
        upperBounds.add(upperBound);
    }

    // update the upper bounds based on the actual keys
    for (int i = 0; i < uniqueKeys.size(); i++) {
        K key = uniqueKeys.get(i);
        int upperBound = upperBounds.get(i);
        for (int j = i + 1; j < keys.size(); j++) {
            K otherKey = keys.get(j);
            if (otherKey.compareTo(key) <= 0) {
                int otherUpperBound = upperBounds.get(j);
                if (upperBound > otherUpperBound) {
                    upperBound = otherUpperBound;
                }
            }
        }
        upperBounds.set(i, upperBound);
    }

    return upperBounds;
}

