public static int indexOfExtension(String filename) {
    // Check if the input is null
    if (filename == null) {
        return -1;
    }

    // Find the last extension separator
    int extensionIndex = filename.lastIndexOf(".");

    // Check if there is a directory separator after the last dot
    if (indexOfLastSeparator(filename) > extensionIndex) {
        return -1;
    }

    // Return the index of the last extension separator
    return extensionIndex;
}

public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastUnix = filename.lastIndexOf("/");
    int lastWindows = filename.lastIndexOf("\\");
    return Math.max(lastUnix, lastWindows);
}

