public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // 1. Validate input parameters
    if (file == null || !file.exists()) {
        throw new IOException("Invalid input file");
    }
    if (timeRanges == null || timeRanges.size() == 0) {
        throw new IOException("Invalid timeRange");
    }

    // 2. Load thread snapshot data from file
    ThreadSnapshotReader reader = new ThreadSnapshotReader(file);
    List<ThreadSnapshot> threadSnapshots = reader.readThreadSnapshots();

    // 3. Filter thread snapshots by time range
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : threadSnapshots) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(snapshot.getProfileAnalyzeTime())) {
                filteredSnapshots.add(snapshot);
                break;
            }
        }
    }

    // 4. Return filtered thread snapshot data
    return filteredSnapshots;
}
